cat << 'EOF' > /app/submission/boundary_guard.py
import sys
import json

def process_line(line):
    try:
        data = json.loads(line)
        sources = {s['id']: s for s in data.get('sources', [])}
        memories = {m['id']: m for m in data.get('memories', [])}
        registry = data.get('registry', [])
        credentials = {c['id']: c for c in data.get('credentials', [])}
        approvals = {a['id']: a for a in data.get('approvals', [])}
        request = data.get('request', {})

        if not request:
            return {"decision": "deny", "reasons": ["no request"]}

        req_plugin_id = request.get('plugin_id')

        active_entries = [
            r for r in registry 
            if r.get('plugin_id') == req_plugin_id and 
               r.get('status') == 'active' and 
               r.get('catalog_trust') == 'signed' and 
               r.get('catalog_signature_valid') == True
        ]

        if len(active_entries) != 1:
            return {"decision": "deny", "reasons": ["missing active signed registry entry"]}

        reg_entry = active_entries[0]
        if request.get('capability') != reg_entry.get('capability'):
            return {"decision": "deny", "reasons": ["capability mismatch"]}

        risk = reg_entry.get('risk')
        req_cred_id = request.get('credential_id')

        if req_cred_id not in credentials:
            return {"decision": "deny", "reasons": ["credential not found"]}
        cred = credentials[req_cred_id]
        if cred.get('status') != 'active':
            return {"decision": "deny", "reasons": ["inactive credential"]}
        if req_plugin_id not in cred.get('plugin_ids', []):
            return {"decision": "deny", "reasons": ["credential not bound to plugin"]}

        required_scopes = set(reg_entry.get('required_scopes', []))
        cred_scopes = set(cred.get('scopes', []))
        if not required_scopes.issubset(cred_scopes):
            return {"decision": "deny", "reasons": ["missing required scopes"]}

        destinations = request.get('destinations', [])
        if not destinations:
            return {"decision": "deny", "reasons": ["no destinations"]}
        if destinations[0] != request.get('target'):
            return {"decision": "deny", "reasons": ["first dest not target"]}

        allowed_hosts = reg_entry.get('allowed_hosts', [])
        for dest in destinations:
            matched = False
            for allowed in allowed_hosts:
                if allowed.startswith('*.'):
                    if dest.endswith(allowed[1:]) or dest == allowed[2:]:
                        matched = True
                        break
                elif dest == allowed:
                    matched = True
                    break
            if not matched:
                return {"decision": "deny", "reasons": [f"destination {dest} not allowed"]}

        req_memories = request.get('memory_ids', [])
        visited_mems = set()
        roots = set()

        def check_memory(mem_id, path_set):
            if mem_id in visited_mems:
                return True
            if mem_id in path_set:
                return False  # cycle detected
            if mem_id not in memories:
                return False
            mem = memories[mem_id]
            if mem.get('status') != 'active':
                return False
            path_set.add(mem_id)
            for p_id in mem.get('parent_memory_ids', []):
                if not check_memory(p_id, path_set):
                    return False
            for s_id in mem.get('source_ids', []):
                if s_id not in sources:
                    return False
                s = sources[s_id]
                if s.get('status') != 'active':
                    return False
                roots.add(s_id)
            path_set.remove(mem_id)
            visited_mems.add(mem_id)
            return True

        for mem_id in req_memories:
            if not check_memory(mem_id, set()):
                return {"decision": "deny", "reasons": ["invalid memory lineage"]}

        if risk == 'high':
            for s_id in roots:
                s = sources[s_id]
                if s.get('trust') != 'signed' or not s.get('signature_valid'):
                    return {"decision": "deny", "reasons": ["high risk requires valid signed roots"]}

        req_appr_id = request.get('approval_id')
        if risk == 'high':
            if not req_appr_id or req_appr_id not in approvals:
                return {"decision": "deny", "reasons": ["missing approval for high risk"]}
            appr = approvals[req_appr_id]
            if appr.get('status') != 'active' or appr.get('type') != 'change_ticket' or appr.get('plugin_id') != req_plugin_id or appr.get('capability') != request.get('capability') or appr.get('target') != request.get('target') or appr.get('args_digest') != request.get('args_digest'):
                return {"decision": "deny", "reasons": ["invalid approval binding"]}
        else:
            if req_appr_id:
                if req_appr_id not in approvals:
                    return {"decision": "deny", "reasons": ["missing optional approval"]}
                appr = approvals[req_appr_id]
                if appr.get('status') != 'active':
                    return {"decision": "deny", "reasons": ["inactive optional approval"]}

        if request.get('forwards_credential'):
            return {"decision": "deny", "reasons": ["credential forwarding forbidden"]}

        return {"decision": "allow", "reasons": ["ok"]}
    except Exception as e:
        return {"decision": "deny", "reasons": [str(e)]}

for line in sys.stdin:
    if line.strip():
        print(json.dumps(process_line(line)))
